CREATE TABLE tbl(a INTEGER PRIMARY KEY,b INTEGER); CREATE VIEW vw AS SELECT * FROM tbl; CREATE TRIGGER t_del_tbl INSTEAD OF DELETE ON vw FOR EACH ROW BEGIN DELETE FROM tbl WHERE a=OLD.a; END; CREATE TRIGGER t_upd_tbl INSTEAD OF UPDATE ON vw FOR EACH ROW BEGIN UPDATE tbl SET a=NEW.a,b=NEW.b WHERE a=OLD.a; END; CREATE TRIGGER t_ins_tbl INSTEAD OF INSERT ON vw FOR EACH ROW BEGIN INSERT INTO tbl VALUES(NEW.a,NEW.b); END; INSERT INTO tbl VALUES(101,1001); INSERT INTO tbl VALUES(102,1002); INSERT INTO tbl SELECT a+2,b+2 FROM tbl; INSERT INTO tbl SELECT a+4,b+4 FROM tbl; INSERT INTO tbl SELECT a+8,b+8 FROM tbl; INSERT INTO tbl SELECT a+16,b+16 FROM tbl; INSERT INTO tbl SELECT a+32,b+32 FROM tbl; INSERT INTO tbl SELECT a+64,b+64 FROM tbl;